import{_ as t,o as a,c as n,ag as i}from"./chunks/framework.DXGyWiRo.js";const p=JSON.parse('{"title":"Security Zero-Trust Guide","description":"","frontmatter":{},"headers":[],"relativePath":"security-zero-trust-guide.md","filePath":"security-zero-trust-guide.md","lastUpdated":1777882948000}'),r={name:"security-zero-trust-guide.md"};function o(s,e,l,c,d,u){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="security-zero-trust-guide" tabindex="-1">Security Zero-Trust Guide <a class="header-anchor" href="#security-zero-trust-guide" aria-label="Permalink to &quot;Security Zero-Trust Guide&quot;">​</a></h1><p>This guide applies zero-trust networking principles to RustChat deployments. In a zero-trust model, no user, device, or service is implicitly trusted — every access request is authenticated, authorized, and encrypted.</p><h2 id="target-audience" tabindex="-1">Target Audience <a class="header-anchor" href="#target-audience" aria-label="Permalink to &quot;Target Audience&quot;">​</a></h2><p>Security-conscious operators, infrastructure engineers, and compliance teams running RustChat in regulated or high-threat environments.</p><hr><h2 id="network-segmentation" tabindex="-1">Network Segmentation <a class="header-anchor" href="#network-segmentation" aria-label="Permalink to &quot;Network Segmentation&quot;">​</a></h2><h3 id="principle" tabindex="-1">Principle <a class="header-anchor" href="#principle" aria-label="Permalink to &quot;Principle&quot;">​</a></h3><p>No data store or internal service should be directly reachable from the public internet. Assume breach: if an attacker gains access to one component, they should not automatically gain access to everything else.</p><h3 id="rustchat-architecture-segments" tabindex="-1">RustChat Architecture Segments <a class="header-anchor" href="#rustchat-architecture-segments" aria-label="Permalink to &quot;RustChat Architecture Segments&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐</span></span>
<span class="line"><span>│   Internet      │</span></span>
<span class="line"><span>│  (untrusted)    │</span></span>
<span class="line"><span>└────────┬────────┘</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>    ┌────┴────┐</span></span>
<span class="line"><span>    │  WAF /  │</span></span>
<span class="line"><span>    │  LB     │</span></span>
<span class="line"><span>    └────┬────┘</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>┌────────┴────────┐</span></span>
<span class="line"><span>│  Reverse Proxy  │  ← TLS termination, rate limiting, IP allowlisting</span></span>
<span class="line"><span>│  (DMZ/trusted)  │</span></span>
<span class="line"><span>└────────┬────────┘</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>    ┌────┴────┐</span></span>
<span class="line"><span>    │RustChat │  ← Application layer</span></span>
<span class="line"><span>    │ Backend │</span></span>
<span class="line"><span>    └────┬────┘</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>    ┌────┴────┐</span></span>
<span class="line"><span>    │  Data   │</span></span>
<span class="line"><span>    │  Tier   │  ← PostgreSQL, Redis, S3-compatible storage (private subnet only)</span></span>
<span class="line"><span>    └─────────┘</span></span></code></pre></div><h3 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h3><ol><li><strong>Database (PostgreSQL):</strong> Bind to a private IP or Unix socket. Block port <code>5432</code> at the host and network firewall. RustChat should be the only service that can reach it.</li><li><strong>Redis:</strong> Bind to <code>127.0.0.1</code> (single node) or a private VPC subnet (clustered). Never expose <code>6379</code> publicly.</li><li><strong>S3-compatible storage:</strong> Run RustFS on an internal network or use a cloud VPC endpoint. If public access to uploaded files is required, serve them through a CDN or signed-URL proxy, not direct bucket access.</li><li><strong>Push Proxy:</strong> If running as a sidecar, bind to <code>localhost</code> or an internal Docker network. The push proxy should not accept requests from the internet.</li></ol><hr><h2 id="authentication-everywhere" tabindex="-1">Authentication Everywhere <a class="header-anchor" href="#authentication-everywhere" aria-label="Permalink to &quot;Authentication Everywhere&quot;">​</a></h2><h3 id="no-implicit-trust-between-services" tabindex="-1">No Implicit Trust Between Services <a class="header-anchor" href="#no-implicit-trust-between-services" aria-label="Permalink to &quot;No Implicit Trust Between Services&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Connection</th><th>Authentication Mechanism</th></tr></thead><tbody><tr><td>Client → Backend</td><td>JWT (Argon2-hashed passwords)</td></tr><tr><td>Backend → PostgreSQL</td><td>Username/password + TLS</td></tr><tr><td>Backend → Redis</td><td>Redis AUTH + TLS</td></tr><tr><td>Backend → S3</td><td>HMAC access/secret keys</td></tr><tr><td>Backend → Push Proxy</td><td>Shared secret (<code>PUSH_PROXY_AUTH_KEY</code>)</td></tr><tr><td>Push Proxy → FCM</td><td>Service account JWT</td></tr><tr><td>Push Proxy → APNS</td><td>Apple JWT (p8 key)</td></tr></tbody></table><h3 id="service-to-service-checklist" tabindex="-1">Service-to-Service Checklist <a class="header-anchor" href="#service-to-service-checklist" aria-label="Permalink to &quot;Service-to-Service Checklist&quot;">​</a></h3><ul><li>[ ] Every internal connection uses credentials, not just IP allowlisting.</li><li>[ ] Credentials are unique per service pair (do not reuse the same Redis password for unrelated applications).</li><li>[ ] mTLS is preferred where supported (PostgreSQL client certs, Redis TLS with client verification).</li></ul><hr><h2 id="api-key-and-token-lifecycle-management" tabindex="-1">API Key and Token Lifecycle Management <a class="header-anchor" href="#api-key-and-token-lifecycle-management" aria-label="Permalink to &quot;API Key and Token Lifecycle Management&quot;">​</a></h2><h3 id="jwt-tokens" tabindex="-1">JWT Tokens <a class="header-anchor" href="#jwt-tokens" aria-label="Permalink to &quot;JWT Tokens&quot;">​</a></h3><ul><li><strong>Expiry:</strong> Default is 24 hours (<code>RUSTCHAT_JWT_EXPIRY_HOURS</code>). In high-security environments, reduce this to 4–8 hours and require re-authentication.</li><li><strong>Refresh:</strong> RustChat does not implement refresh tokens natively. Users must re-login when JWTs expire. For long-lived mobile sessions, ensure devices are enrolled and trackable.</li><li><strong>Revocation:</strong> Changing <code>RUSTCHAT_JWT_SECRET</code> revokes all tokens globally. There is no per-user revocation mechanism; plan incident response accordingly.</li></ul><h3 id="s3-credentials" tabindex="-1">S3 Credentials <a class="header-anchor" href="#s3-credentials" aria-label="Permalink to &quot;S3 Credentials&quot;">​</a></h3><ul><li>Rotate access keys every 90 days.</li><li>Use IAM-style policies scoped to a single bucket and action set.</li><li>Avoid long-lived credentials. If your S3 provider supports STS or presigned URLs, prefer those for external integrations.</li></ul><h3 id="push-proxy-secrets" tabindex="-1">Push Proxy Secrets <a class="header-anchor" href="#push-proxy-secrets" aria-label="Permalink to &quot;Push Proxy Secrets&quot;">​</a></h3><ul><li><code>PUSH_PROXY_AUTH_KEY</code> should be rotated if any backend instance is compromised.</li><li>APNS p8 keys do not expire, but can be revoked in the Apple Developer Portal.</li></ul><hr><h2 id="principle-of-least-privilege-for-users-and-roles" tabindex="-1">Principle of Least Privilege for Users and Roles <a class="header-anchor" href="#principle-of-least-privilege-for-users-and-roles" aria-label="Permalink to &quot;Principle of Least Privilege for Users and Roles&quot;">​</a></h2><h3 id="built-in-roles" tabindex="-1">Built-in Roles <a class="header-anchor" href="#built-in-roles" aria-label="Permalink to &quot;Built-in Roles&quot;">​</a></h3><p>RustChat supports role-based access control. Default roles include:</p><ul><li><code>system_admin</code>: Full access. Minimize the number of accounts with this role.</li><li><code>team_admin</code>: Team-level administration.</li><li><code>user</code>: Standard participation.</li></ul><h3 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h3><ol><li><strong>Grant <code>system_admin</code> to no more than 2–3 accounts.</strong> Use named accounts, not shared credentials.</li><li><strong>Audit role assignments quarterly.</strong> Remove elevated roles from users who no longer need them.</li><li><strong>Disable or delete stale accounts.</strong> Inactive accounts are attack surface.</li><li><strong>Use channel-level privacy settings.</strong> Default sensitive channels to private.</li></ol><hr><h2 id="session-management-and-timeout-policies" tabindex="-1">Session Management and Timeout Policies <a class="header-anchor" href="#session-management-and-timeout-policies" aria-label="Permalink to &quot;Session Management and Timeout Policies&quot;">​</a></h2><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><ul><li>Set <code>RUSTCHAT_JWT_EXPIRY_HOURS</code> to match your organization&#39;s session policy.</li><li>In production, enforce short sessions and require password re-entry for sensitive actions (admin settings, user deletion).</li></ul><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ol><li><strong>Invalidate sessions on password change.</strong> When a user resets their password, all existing JWTs should be considered invalid. Since RustChat does not maintain a token blocklist, this requires rotating <code>RUSTCHAT_JWT_SECRET</code> or accepting the limitation until a session revocation feature is added.</li><li><strong>Detect anomalous sessions.</strong> Monitor for: <ul><li>Logins from new geolocations or ASNs</li><li>Multiple concurrent sessions from different regions</li><li>WebSocket connections without preceding HTTP authentication</li></ul></li><li><strong>Require MFA where available.</strong> If your identity provider supports OAuth2/OIDC with MFA, prefer that over local password authentication.</li></ol><hr><h2 id="forward-secrecy-and-tls-best-practices" tabindex="-1">Forward Secrecy and TLS Best Practices <a class="header-anchor" href="#forward-secrecy-and-tls-best-practices" aria-label="Permalink to &quot;Forward Secrecy and TLS Best Practices&quot;">​</a></h2><h3 id="tls-configuration" tabindex="-1">TLS Configuration <a class="header-anchor" href="#tls-configuration" aria-label="Permalink to &quot;TLS Configuration&quot;">​</a></h3><ol><li><strong>TLS 1.3 only.</strong> Disable TLS 1.0, 1.1, and 1.2 cipher suites that lack forward secrecy.</li><li><strong>Use ECDSA or RSA certificates with strong key lengths</strong> (P-256 or RSA 2048+).</li><li><strong>Enable OCSP stapling</strong> on your reverse proxy for faster revocation checks.</li><li><strong>HSTS header:</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Strict-Transport-Security: max-age=63072000; includeSubDomains; preload</span></span></code></pre></div></li></ol><h3 id="forward-secrecy" tabindex="-1">Forward Secrecy <a class="header-anchor" href="#forward-secrecy" aria-label="Permalink to &quot;Forward Secrecy&quot;">​</a></h3><p>Ensure your TLS configuration uses ephemeral key exchange (ECDHE). This prevents past traffic from being decrypted if the server&#39;s private key is later compromised.</p><h3 id="internal-tls" tabindex="-1">Internal TLS <a class="header-anchor" href="#internal-tls" aria-label="Permalink to &quot;Internal TLS&quot;">​</a></h3><p>Where possible, encrypt traffic between internal services:</p><ul><li>Backend → PostgreSQL (<code>sslmode=require</code>)</li><li>Backend → Redis (<code>rediss://</code>)</li><li>Backend → S3-compatible storage (HTTPS endpoint)</li></ul><hr><h2 id="monitoring-and-anomaly-detection" tabindex="-1">Monitoring and Anomaly Detection <a class="header-anchor" href="#monitoring-and-anomaly-detection" aria-label="Permalink to &quot;Monitoring and Anomaly Detection&quot;">​</a></h2><h3 id="key-metrics-to-alert-on" tabindex="-1">Key Metrics to Alert On <a class="header-anchor" href="#key-metrics-to-alert-on" aria-label="Permalink to &quot;Key Metrics to Alert On&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Signal</th><th>Threshold</th><th>Indication</th></tr></thead><tbody><tr><td>Failed login rate</td><td>&gt; 5/min per IP</td><td>Brute-force attempt</td></tr><tr><td>JWT validation failures</td><td>Spike above baseline</td><td>Token replay or tampering</td></tr><tr><td>403/401 rate</td><td>&gt; 10% of total</td><td>Credential stuffing or scanning</td></tr><tr><td>WebSocket connection rate</td><td>&gt; 100/min per IP</td><td>Possible DoS or bot</td></tr><tr><td>File upload volume</td><td>&gt; 3x baseline</td><td>Data exfiltration or abuse</td></tr><tr><td>Admin action count</td><td>Unusual off-hours</td><td>Compromised admin account</td></tr></tbody></table><h3 id="log-correlation" tabindex="-1">Log Correlation <a class="header-anchor" href="#log-correlation" aria-label="Permalink to &quot;Log Correlation&quot;">​</a></h3><p>Centralize logs from:</p><ul><li>Reverse proxy (access logs)</li><li>RustChat backend (application logs)</li><li>PostgreSQL (connection logs, slow queries)</li><li>Redis (command logs in ACL mode)</li><li>S3-compatible storage (access logs)</li></ul><p>Use correlation rules to detect multi-stage attacks (e.g., login failure followed by successful login from a new IP, followed by admin action).</p><h3 id="tooling" tabindex="-1">Tooling <a class="header-anchor" href="#tooling" aria-label="Permalink to &quot;Tooling&quot;">​</a></h3><ul><li><strong>Open source:</strong> Wazuh, Falco, Suricata</li><li><strong>Commercial:</strong> Datadog Security Monitoring, Splunk ES, Elastic Security</li><li><strong>Cloud-native:</strong> AWS GuardDuty, GCP Security Command Center</li></ul><hr><h2 id="incident-response-basics-for-self-hosted-operators" tabindex="-1">Incident Response Basics for Self-Hosted Operators <a class="header-anchor" href="#incident-response-basics-for-self-hosted-operators" aria-label="Permalink to &quot;Incident Response Basics for Self-Hosted Operators&quot;">​</a></h2><h3 id="preparation" tabindex="-1">Preparation <a class="header-anchor" href="#preparation" aria-label="Permalink to &quot;Preparation&quot;">​</a></h3><ol><li><strong>Maintain an offline contact list</strong> for your team and hosting provider.</li><li><strong>Document your RustChat deployment topology</strong> (versions, hostnames, backup locations).</li><li><strong>Keep GPG-encrypted backups</strong> of critical secrets in a separate location.</li></ol><h3 id="detection" tabindex="-1">Detection <a class="header-anchor" href="#detection" aria-label="Permalink to &quot;Detection&quot;">​</a></h3><ol><li><strong>Set up real-time alerting</strong> on the signals listed above.</li><li><strong>Review logs daily</strong> during the first weeks of production deployment.</li></ol><h3 id="containment" tabindex="-1">Containment <a class="header-anchor" href="#containment" aria-label="Permalink to &quot;Containment&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>Immediate Action</th></tr></thead><tbody><tr><td>Suspected credential leak</td><td>Rotate <code>RUSTCHAT_JWT_SECRET</code> and all service passwords</td></tr><tr><td>Confirmed admin account compromise</td><td>Demote or disable the account; audit admin logs</td></tr><tr><td>Database exposure</td><td>Block DB port; rotate DB password; check for unauthorized queries</td></tr><tr><td>File upload abuse</td><td>Disable uploads temporarily; review uploaded files</td></tr><tr><td>DDoS / volumetric attack</td><td>Enable Cloudflare or upstream DDoS protection; scale backend horizontally</td></tr></tbody></table><h3 id="eradication-and-recovery" tabindex="-1">Eradication and Recovery <a class="header-anchor" href="#eradication-and-recovery" aria-label="Permalink to &quot;Eradication and Recovery&quot;">​</a></h3><ol><li><strong>Identify the root cause</strong> before restoring services. A quick restore without patching the entry point invites reinfection.</li><li><strong>Restore from known-good backups</strong> if data integrity is in question.</li><li><strong>Rotate all secrets</strong> after a confirmed breach.</li><li><strong>Document lessons learned</strong> and update runbooks.</li></ol><h3 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h3><ul><li>Notify affected users if personal data was accessed.</li><li>Follow your jurisdiction&#39;s breach notification laws (GDPR, CCPA, etc.).</li><li>For vulnerabilities in RustChat itself, report privately per <code>SECURITY.md</code>.</li></ul><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Zero trust is not a single product or configuration flag — it is a continuous practice:</p><ol><li><strong>Verify explicitly.</strong> Every request is authenticated and authorized.</li><li><strong>Use least privilege.</strong> Users and services get only the access they need.</li><li><strong>Assume breach.</strong> Segment networks, encrypt data in transit and at rest, and monitor for anomalies.</li><li><strong>Rotate and revoke.</strong> Credentials and tokens have a finite lifetime.</li></ol><p>For concrete hardening steps (TLS setup, rate limiting, secret generation), see <a href="./security-deployment-guide"><code>docs/security-deployment-guide.md</code></a>.</p>`,75)])])}const g=t(r,[["render",o]]);export{p as __pageData,g as default};
